#ifndef HEAP_TIMER_H
#define HEAP_TIMER_H

#include <chrono>
#include <deque>
#include <functional>
#include <iostream>
#include <map>
#include <unordered_map>

namespace log {
class Logger;
}

namespace heap_timer {

using Clock = std::chrono::steady_clock;
using TimeOutCallback = std::function<void(const int&)>; // Assuming Key is int for simplicity
using Key = int;

struct Node {
    Key key;
    Clock::time_point expiration;
    TimeOutCallback callback;

    Node() : key(0), expiration(Clock::now()), callback([](const Key&){}) {}

    bool Expired() const {
        return Clock::now() >= expiration;
    }

    void Swap(Node& o) noexcept {
        std::swap(key, o.key);
        std::swap(expiration, o.expiration);
        std::swap(callback, o.callback);
    }
};

class HeapTimer {
public:
    HeapTimer(log::Logger::Ptr logger = log::Logger::GetRoot());

    void Adjust(const Key& key, Clock::duration expiration);
    void Adjust(const Key& key, Clock::time_point expiration);

    void Push(const Key& key, Clock::duration expiration, TimeOutCallback callback);
    void Push(const Key& key, Clock::time_point expiration, TimeOutCallback callback);

    void Tick();
    void Remove(const Key& key);
    void Invoke(const Key& key);
    Node Pop();
    void Clear();
    bool Contain(const Key& key) const;
    bool Empty() const;
    size_t Size() const;
    Clock::duration ToNextTick() const;

private:
    log::Logger::Ptr logger_; 
    std::unordered_map<Key, size_t> key_to_idx_; 
    std::deque<Node> nodes_; 
};
}

#endif // HEAP_TIMER_H
